head.b:skin:
/* Rota Tour — tema Blogger (mesmo visual do site em Next.js) */

:root{
  --surface:#ffffff; --surface-sky:#ecfbfc; --surface-muted:#f3f6f8; --mist:#caf5f7;
  --line:#d6e4ec; --line-strong:#6f7f99;
  --ink:#0b2975; --ink-body:#3b4b6b; --ink-muted:#5a6782;
  --sky:#1cabb0; --on-sky:#0b2975; --accent-text:#0a7276; --link:#0a7276;
  --primary:#0b2975; --on-primary:#ffffff;
  --navy:#0b2975; --on-navy:#ffffff; --on-navy-muted:#caf5f7;
  --focus:#0a7276; --success:#1e7a4f; --danger:#b3261e;
  --scrim:rgba(11,26,61,.66);
  --shadow-sm:0 1px 2px rgba(11,41,117,.06),0 2px 8px rgba(11,41,117,.05);
  --shadow-md:0 10px 30px rgba(11,41,117,.12);
  --space-1:4px; --space-2:8px; --space-3:12px; --space-4:16px; --space-5:24px; --space-6:32px; --space-7:48px; --space-8:72px; --space-9:112px;
  --radius-sm:8px; --radius-md:14px; --radius-lg:24px; --radius-pill:999px;
  --font-display:Fraunces,"Iowan Old Style",Georgia,serif;
  --font-sans:Manrope,"Segoe UI",system-ui,-apple-system,sans-serif;
  color-scheme:light;
}
@media (prefers-color-scheme: dark){
  :root{
    --surface:#0b1a3d; --surface-sky:#12245a; --surface-muted:#0f2049; --mist:#12245a;
    --line:#233a6e; --line-strong:#6d7da3;
    --ink:#eaf6fc; --ink-body:#c4cce0; --ink-muted:#97a3bf;
    --on-sky:#0b1a3d; --accent-text:#5ed6da; --link:#5ed6da;
    --primary:#1cabb0; --on-primary:#0b1a3d;
    --navy:#081330; --on-navy:#eaf6fc; --focus:#5ed6da;
    --success:#6fd3a0; --danger:#ff9a8f; --scrim:rgba(5,12,30,.72);
    --shadow-sm:0 1px 2px rgba(0,0,0,.3); --shadow-md:0 10px 30px rgba(0,0,0,.45);
    color-scheme:dark;
  }
}
html{scroll-behavior:smooth}
body{background:var(--surface)}

/* Rota Tour — component styles. Every value comes from tokens.css (var(--…)). */
body { margin: 0; }
.rt, .rt * { box-sizing: border-box; }
.rt { font-family: var(--font-sans); font-size: 16px; line-height: 26px; color: var(--ink-body); background: var(--surface); -webkit-font-smoothing: antialiased; }
:where(.rt) h1, :where(.rt) h2, :where(.rt) h3 { font-family: var(--font-display); color: var(--ink); font-weight: 600; margin: 0; }
:where(.rt) p { margin: 0; }
:where(.rt) a { color: inherit; }
:where(.rt) img { max-width: 100%; display: block; }
.rt :focus-visible { outline: 2px solid var(--focus); outline-offset: 2px; }
.rt [id] { scroll-margin-top: 92px; }
.rt-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }
.rt-container { width: 100%; max-width: 1200px; margin: 0 auto; padding: 0 var(--space-7); }
.rt-icon { flex: none; display: inline-block; vertical-align: middle; }
.rt-eyebrow { font-size: 12px; line-height: 16px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: var(--accent-text); }
.rt-skip { position: absolute; left: var(--space-4); top: -60px; z-index: 50; background: var(--primary); color: var(--on-primary); padding: var(--space-2) var(--space-4); border-radius: var(--radius-pill); font-weight: 600; text-decoration: none; }
.rt-skip:focus { top: var(--space-3); }

/* Button */
.rt-btn { display: inline-flex; align-items: center; justify-content: center; gap: var(--space-2); height: 44px; padding: 0 22px; border-radius: var(--radius-pill); border: 1.5px solid transparent; font: 600 15px/20px var(--font-sans); text-decoration: none; cursor: pointer; white-space: nowrap; transition: background-color .18s ease, border-color .18s ease, color .18s ease, transform .18s ease, box-shadow .18s ease; }
.rt-btn:hover { transform: translateY(-1px); box-shadow: var(--shadow-sm); }
.rt-btn:active { transform: translateY(0); box-shadow: none; }
.rt-btn[disabled] { opacity: .5; cursor: not-allowed; transform: none; box-shadow: none; }
.rt-btn-lg { height: 52px; padding: 0 28px; font-size: 16px; }
.rt-btn-sm { height: 36px; padding: 0 16px; font-size: 14px; }
.rt-btn-primary { background: var(--primary); color: var(--on-primary); }
.rt-btn-primary:hover { filter: brightness(1.12); }
.rt-btn-sky { background: var(--sky); color: var(--on-sky); }
.rt-btn-sky:hover { filter: brightness(1.05); }
.rt-btn-ghost { background: transparent; color: var(--ink); border-color: var(--line-strong); }
.rt-btn-ghost:hover { background: var(--surface-sky); }
.rt-btn-light { background: rgba(255, 255, 255, .14); color: #ffffff; border-color: rgba(255, 255, 255, .8); }
.rt-btn-light:hover { background: rgba(255, 255, 255, .24); }
.rt-btn-link { height: auto; padding: 0; border: 0; background: none; color: var(--accent-text); }
.rt-btn-link:hover { transform: none; box-shadow: none; text-decoration: underline; text-underline-offset: 4px; }
.rt-btn-link .rt-icon { transition: transform .18s ease; }
.rt-btn-link:hover .rt-icon { transform: translateX(3px); }

/* Header */
.rt-header { position: sticky; top: 0; z-index: 20; background: var(--surface); border-bottom: 1px solid var(--line); }
.rt-header-bar { display: flex; align-items: center; gap: var(--space-6); height: 76px; }
.rt-brand { display: inline-flex; align-items: center; gap: 10px; text-decoration: none; color: var(--ink); font: 600 24px/28px var(--font-display); letter-spacing: -.01em; }
.rt-brand-mark { width: 36px; height: 36px; border-radius: var(--radius-pill); background: var(--sky); color: var(--on-sky); display: inline-flex; align-items: center; justify-content: center; }
.rt-nav { margin-left: auto; }
.rt-nav ul { list-style: none; margin: 0; padding: 0; display: flex; gap: var(--space-5); }
.rt-nav a { position: relative; display: inline-block; padding: var(--space-2) 0; font: 600 15px/20px var(--font-sans); color: var(--ink); text-decoration: none; }
.rt-nav a::after { content: ""; position: absolute; left: 0; right: 0; bottom: 2px; height: 2px; border-radius: 2px; background: var(--sky); transform: scaleX(0); transform-origin: left; transition: transform .2s ease; }
.rt-nav a:hover::after, .rt-nav a[aria-current="page"]::after { transform: scaleX(1); }
.rt-menu-btn { display: none; margin-left: auto; width: 44px; height: 44px; border-radius: var(--radius-pill); border: 1.5px solid var(--line-strong); background: var(--surface); color: var(--ink); cursor: pointer; align-items: center; justify-content: center; }
.rt-mobile { display: none; }
@media (max-width: 1080px) {
  .rt-nav, .rt-header-cta { display: none; }
  .rt-menu-btn { display: inline-flex; }
  .rt-mobile[data-open="true"] { display: block; border-top: 1px solid var(--line); background: var(--surface); box-shadow: var(--shadow-md); }
  .rt-mobile ul { list-style: none; margin: 0; padding: var(--space-3) 0; }
  .rt-mobile a.rt-mobile-link { display: block; padding: var(--space-3) 0; font: 600 17px/24px var(--font-sans); color: var(--ink); text-decoration: none; border-bottom: 1px solid var(--line); }
  .rt-mobile .rt-btn { width: 100%; margin: var(--space-4) 0 var(--space-5); }
}

/* Sections */
.rt-section { padding: var(--space-8) 0; }
.rt-section-muted { background: var(--surface-muted); }
.rt-section-sky { background: var(--surface-sky); }
.rt-section-head { display: flex; align-items: flex-end; justify-content: space-between; gap: var(--space-5); margin-bottom: var(--space-7); }
.rt-section-head h2 { font-size: 32px; line-height: 38px; letter-spacing: -.01em; margin-top: var(--space-2); }
.rt-section-head p { margin-top: var(--space-3); max-width: 560px; }

/* Hero */
.rt-hero { padding: var(--space-4) 0 0; }
.rt-hero-frame { position: relative; overflow: hidden; border-radius: var(--radius-lg); min-height: 580px; display: flex; align-items: center; }
.rt-hero-frame > img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
.rt-hero-frame::before { content: ""; position: absolute; inset: 0; z-index: 1; background: linear-gradient(90deg, var(--scrim) 0%, var(--scrim) 38%, rgba(11, 41, 117, 0) 78%); }
.rt-hero-copy { position: relative; z-index: 2; max-width: 620px; padding: var(--space-9) var(--space-7); color: #ffffff; }
.rt-hero-copy h1 { color: #ffffff; font-size: 56px; line-height: 60px; letter-spacing: -.02em; }
.rt-hero-copy p { margin-top: var(--space-5); font-size: 19px; line-height: 30px; color: #ffffff; max-width: 520px; }
.rt-hero-actions { display: flex; flex-wrap: wrap; gap: var(--space-3); margin-top: var(--space-6); }

/* Category card */
.rt-cat-grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: var(--space-5); }
.rt-cat { display: flex; flex-direction: column; gap: var(--space-3); padding: var(--space-5); background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius-md); box-shadow: var(--shadow-sm); text-decoration: none; transition: transform .2s ease, box-shadow .2s ease; }
.rt-cat:hover { transform: translateY(-3px); box-shadow: var(--shadow-md); }
.rt-cat-icon { width: 52px; height: 52px; border-radius: var(--radius-pill); background: var(--surface-sky); color: var(--ink); display: inline-flex; align-items: center; justify-content: center; margin-bottom: var(--space-2); transition: background-color .2s ease; }
.rt-cat:hover .rt-cat-icon { background: var(--sky); color: var(--on-sky); }
.rt-cat h3 { font-size: 22px; line-height: 28px; }
.rt-cat p { flex: 1; font-size: 15px; line-height: 24px; }
.rt-cat .rt-btn-link { align-self: flex-start; }

/* Article card */
.rt-art-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: var(--space-5); }
.rt-art { display: flex; flex-direction: column; background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius-md); overflow: hidden; box-shadow: var(--shadow-sm); text-decoration: none; transition: transform .2s ease, box-shadow .2s ease; }
.rt-art:hover { transform: translateY(-3px); box-shadow: var(--shadow-md); }
.rt-art-media { aspect-ratio: 16 / 10; overflow: hidden; background: var(--surface-sky); }
.rt-art-media img { width: 100%; height: 100%; object-fit: cover; transition: transform .5s ease; }
.rt-art:hover .rt-art-media img { transform: scale(1.04); }
.rt-art-body { display: flex; flex-direction: column; gap: var(--space-2); padding: var(--space-5); flex: 1; }
.rt-art h3 { font-size: 21px; line-height: 27px; margin-top: 2px; }
.rt-art-excerpt { font-size: 15px; line-height: 24px; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.rt-meta { display: flex; flex-wrap: wrap; align-items: center; gap: var(--space-1) var(--space-3); margin-top: auto; padding-top: var(--space-3); font-size: 14px; line-height: 20px; font-weight: 500; color: var(--ink-muted); }
.rt-meta span { display: inline-flex; align-items: center; gap: 6px; }

/* Filters */
.rt-filters { display: flex; flex-direction: column; gap: var(--space-4); margin-bottom: var(--space-6); }
.rt-search { position: relative; max-width: 520px; }
.rt-search .rt-icon { position: absolute; left: 18px; top: 50%; transform: translateY(-50%); color: var(--ink-muted); pointer-events: none; }
.rt-input { width: 100%; height: 48px; padding: 0 var(--space-5) 0 48px; border-radius: var(--radius-pill); border: 1.5px solid var(--line-strong); background: var(--surface); color: var(--ink); font: 500 16px/24px var(--font-sans); }
.rt-input::placeholder { color: var(--ink-muted); }
.rt-input:focus { outline: 2px solid var(--focus); outline-offset: 2px; }
.rt-chips { display: flex; flex-wrap: wrap; gap: var(--space-2); }
.rt-chip { height: 36px; padding: 0 16px; border-radius: var(--radius-pill); border: 1.5px solid var(--line-strong); background: var(--surface); color: var(--ink); font: 600 14px/20px var(--font-sans); cursor: pointer; transition: background-color .15s ease, border-color .15s ease; }
.rt-chip:hover { background: var(--surface-sky); }
.rt-chip[aria-pressed="true"] { background: var(--sky); border-color: var(--sky); color: var(--on-sky); }
.rt-count { font-size: 14px; line-height: 20px; color: var(--ink-muted); }
.rt-empty { padding: var(--space-7) var(--space-5); text-align: center; border: 1.5px dashed var(--line-strong); border-radius: var(--radius-md); background: var(--surface); }
.rt-empty h3 { font-size: 22px; line-height: 28px; margin-bottom: var(--space-2); }
.rt-empty .rt-btn { margin-top: var(--space-4); }

/* Routes / transport */
.rt-routes { display: grid; grid-template-columns: 5fr 7fr; gap: var(--space-7); align-items: center; }
.rt-routes-intro h2 { font-size: 36px; line-height: 42px; letter-spacing: -.015em; margin: var(--space-2) 0 var(--space-4); }
.rt-routes-list { display: flex; flex-direction: column; gap: var(--space-4); }
.rt-route { display: grid; grid-template-columns: 200px 1fr; background: var(--surface); border-radius: var(--radius-md); overflow: hidden; box-shadow: var(--shadow-sm); text-decoration: none; transition: transform .2s ease, box-shadow .2s ease; }
.rt-route:hover { transform: translateY(-3px); box-shadow: var(--shadow-md); }
.rt-route img { width: 100%; height: 100%; min-height: 148px; object-fit: cover; }
.rt-route-body { padding: var(--space-5); display: flex; flex-direction: column; gap: var(--space-2); }
.rt-route h3 { font-size: 20px; line-height: 26px; }
.rt-route p { font-size: 15px; line-height: 24px; }

/* Destinations */
.rt-dest-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); grid-auto-rows: 250px; gap: var(--space-4); }
.rt-dest { position: relative; overflow: hidden; border-radius: var(--radius-md); text-decoration: none; color: #ffffff; display: flex; align-items: flex-end; }
.rt-dest-lg { grid-column: span 2; grid-row: span 2; }
.rt-dest-wide { grid-column: span 2; }
.rt-dest img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; transition: transform .6s ease; }
.rt-dest:hover img { transform: scale(1.05); }
.rt-dest::before { content: ""; position: absolute; inset: 0; z-index: 1; background: linear-gradient(0deg, var(--scrim) 0%, var(--scrim) 30%, rgba(11, 41, 117, 0) 72%); }
.rt-dest-copy { position: relative; z-index: 2; padding: var(--space-5); }
.rt-dest h3 { color: #ffffff; font-size: 22px; line-height: 28px; }
.rt-dest-lg h3 { font-size: 30px; line-height: 36px; }
.rt-dest p { margin-top: var(--space-1); font-size: 15px; line-height: 22px; color: #ffffff; max-width: 340px; }
.rt-dest-cta { display: inline-flex; align-items: center; gap: 6px; margin-top: var(--space-3); font: 600 14px/20px var(--font-sans); color: #ffffff; }

/* Newsletter */
.rt-news { position: relative; overflow: hidden; border-radius: var(--radius-lg); background: var(--surface-sky); padding: var(--space-8) var(--space-7); text-align: center; }
.rt-news-clouds { position: absolute; inset: 0; width: 100%; height: 100%; pointer-events: none; }
.rt-news-clouds ellipse { fill: var(--surface); opacity: .7; }
.rt-news-inner { position: relative; max-width: 560px; margin: 0 auto; }
.rt-news h2 { font-size: 32px; line-height: 38px; letter-spacing: -.01em; }
.rt-news-text { margin-top: var(--space-3); }
.rt-news-form { display: flex; gap: var(--space-3); margin-top: var(--space-6); }
.rt-news-form .rt-input { padding-left: var(--space-5); flex: 1; }
.rt-news-form .rt-input[aria-invalid="true"] { border-color: var(--danger); }
.rt-field-msg { display: flex; align-items: center; justify-content: center; gap: 6px; margin-top: var(--space-3); font-size: 14px; line-height: 20px; font-weight: 600; }
.rt-field-error { color: var(--danger); }
.rt-success { display: inline-flex; align-items: center; gap: var(--space-3); margin-top: var(--space-6); padding: var(--space-4) var(--space-5); border-radius: var(--radius-md); background: var(--surface); color: var(--success); font-weight: 600; text-align: left; }
.rt-success span { color: var(--ink); font-weight: 500; }
.rt-demo-note { margin-top: var(--space-4); font-size: 13px; line-height: 18px; color: var(--ink-muted); }

/* Footer */
.rt-footer { background: var(--navy); color: var(--on-navy-muted); padding: var(--space-8) 0 var(--space-6); font-size: 15px; line-height: 24px; }
.rt-footer-grid { display: grid; grid-template-columns: 1.4fr 1fr 1fr 1.2fr; gap: var(--space-7); }
.rt-footer .rt-brand { color: var(--on-navy); }
.rt-footer .rt-brand-mark { background: var(--sky); color: var(--on-sky); }
.rt-footer h3 { font: 700 13px/18px var(--font-sans); letter-spacing: .08em; text-transform: uppercase; color: var(--on-navy); margin-bottom: var(--space-4); }
.rt-footer ul { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: var(--space-2); }
.rt-footer a { color: var(--on-navy); text-decoration: none; }
.rt-footer a:hover { text-decoration: underline; text-underline-offset: 4px; }
.rt-footer-about { margin-top: var(--space-4); max-width: 340px; }
.rt-social { display: flex; flex-wrap: wrap; gap: var(--space-2); margin-top: var(--space-5); }
.rt-social a { display: inline-flex; align-items: center; gap: 6px; height: 34px; padding: 0 14px; border: 1px solid rgba(197, 221, 236, .45); border-radius: var(--radius-pill); font-size: 14px; }
.rt-contact li { display: flex; gap: var(--space-2); align-items: flex-start; }
.rt-contact .rt-icon { margin-top: 3px; color: var(--sky); }
.rt-placeholder { font-style: italic; }
.rt-footer-bottom { display: flex; flex-wrap: wrap; justify-content: space-between; gap: var(--space-3); margin-top: var(--space-7); padding-top: var(--space-5); border-top: 1px solid rgba(197, 221, 236, .25); font-size: 14px; }
.rt-footer-bottom ul { flex-direction: row; gap: var(--space-5); }

/* Article page */
.rt-article { padding: var(--space-7) 0 var(--space-8); }
.rt-article-head { max-width: 760px; margin: 0 auto; }
.rt-back { display: inline-flex; align-items: center; gap: 6px; font: 600 15px/20px var(--font-sans); color: var(--accent-text); text-decoration: none; margin-bottom: var(--space-6); }
.rt-back:hover { text-decoration: underline; text-underline-offset: 4px; }
.rt-article-head h1 { font-size: 42px; line-height: 48px; letter-spacing: -.015em; margin: var(--space-3) 0 var(--space-4); }
.rt-article-cover { max-width: 1000px; margin: var(--space-6) auto 0; border-radius: var(--radius-lg); overflow: hidden; aspect-ratio: 16 / 8; background: var(--surface-sky); }
.rt-article-cover img { width: 100%; height: 100%; object-fit: cover; }
.rt-prose { max-width: 68ch; margin: var(--space-7) auto 0; font-size: 18px; line-height: 30px; color: var(--ink-body); }
.rt-prose > * + * { margin-top: var(--space-5); }
.rt-prose h2 { font-size: 28px; line-height: 34px; margin-top: var(--space-7); }
.rt-prose h3 { font-size: 22px; line-height: 28px; margin-top: var(--space-6); }
.rt-prose ul, .rt-prose ol { padding-left: 1.3em; }
.rt-prose li + li { margin-top: var(--space-2); }
.rt-prose li::marker { color: var(--accent-text); }
.rt-prose strong { color: var(--ink); }
.rt-prose a { color: var(--link); text-underline-offset: 3px; }
.rt-prose blockquote { margin-left: 0; margin-right: 0; padding: var(--space-5); border-radius: var(--radius-md); background: var(--surface-sky); color: var(--ink); font-family: var(--font-display); font-size: 21px; line-height: 30px; }
.rt-prose figure { margin-left: 0; margin-right: 0; }
.rt-prose figure img { border-radius: var(--radius-md); width: 100%; }
.rt-prose figcaption { margin-top: var(--space-2); font-size: 14px; line-height: 20px; color: var(--ink-muted); }
.rt-prose code { font-size: .9em; background: var(--surface-muted); padding: 2px 6px; border-radius: 6px; }
.rt-related { margin-top: var(--space-8); }
.rt-related h2 { font-size: 28px; line-height: 34px; margin-bottom: var(--space-5); }
.rt-doc { max-width: 68ch; margin: 0 auto; padding: var(--space-8) 0; }
.rt-doc h1 { font-size: 42px; line-height: 48px; margin: var(--space-3) 0 var(--space-5); }
.rt-doc p + p { margin-top: var(--space-4); }

/* Responsive */
@media (max-width: 1080px) {
  .rt-cat-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .rt-art-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .rt-routes { grid-template-columns: 1fr; }
  .rt-dest-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .rt-dest-grid > :last-child { grid-column: span 2; }
  .rt-footer-grid { grid-template-columns: 1fr 1fr; }
}
@media (max-width: 640px) {
  .rt-container { padding: 0 var(--space-4); }
  .rt-section { padding: var(--space-7) 0; }
  .rt-header-bar { height: 64px; }
  .rt-hero { padding-top: var(--space-3); }
  .rt-hero-frame { min-height: 520px; align-items: flex-end; }
  .rt-hero-frame::before { background: linear-gradient(0deg, var(--scrim) 0%, var(--scrim) 50%, rgba(11, 41, 117, .15) 100%); }
  .rt-hero-copy { padding: var(--space-6) var(--space-5); }
  .rt-hero-copy h1 { font-size: 38px; line-height: 42px; }
  .rt-hero-copy p { font-size: 17px; line-height: 27px; }
  .rt-hero-actions .rt-btn { width: 100%; }
  .rt-section-head { flex-direction: column; align-items: flex-start; margin-bottom: var(--space-6); }
  .rt-section-head h2, .rt-routes-intro h2, .rt-news h2 { font-size: 28px; line-height: 34px; }
  .rt-cat-grid, .rt-art-grid { grid-template-columns: 1fr; }
  .rt-route { grid-template-columns: 112px 1fr; }
  .rt-route-body { padding: var(--space-4); }
  .rt-dest-grid { grid-template-columns: 1fr; grid-auto-rows: 220px; }
  .rt-dest-lg, .rt-dest-wide, .rt-dest-grid > :last-child { grid-column: span 1; grid-row: span 1; }
  .rt-news { padding: var(--space-7) var(--space-5); }
  .rt-news-form { flex-direction: column; }
  .rt-footer-grid { grid-template-columns: 1fr; gap: var(--space-6); }
  .rt-article-head h1, .rt-doc h1 { font-size: 32px; line-height: 38px; }
  .rt-prose { font-size: 17px; line-height: 28px; }
}
@media (prefers-reduced-motion: reduce) {
  .rt *, .rt *::before, .rt *::after { transition: none !important; animation: none !important; }
}

/* Ajustes do tema Blogger */
.rt-logo img{display:block;height:58px;width:auto}
.rt-logo .logo-claro{display:none}
@media (prefers-color-scheme: dark){ .rt-logo .logo-azul{display:none} .rt-logo .logo-claro{display:block} }
.rt-footer .rt-logo img{height:64px}
.rt-footer .rt-logo .logo-azul{display:none}.rt-footer .rt-logo .logo-claro{display:block}
.rt-cat-icon{background:var(--mist)}
a.rt-chip{display:inline-flex;align-items:center;text-decoration:none}
.rt-chip[aria-current="page"]{background:var(--sky);border-color:var(--sky);color:var(--on-sky)}
.rt-search-form{display:flex;gap:var(--space-3);max-width:620px}
.rt-search-form .rt-search{flex:1;max-width:none}
.rt-handle{display:inline-flex;align-items:center;gap:6px;text-decoration:none;height:34px;padding:0 14px;border:1px solid rgba(202,245,247,.45);border-radius:var(--radius-pill);color:var(--on-navy);font-size:14px;margin-top:var(--space-5)}
.rt-pager{display:flex;justify-content:center;gap:var(--space-3);margin-top:var(--space-7)}
.rt-prose img{max-width:100%;height:auto;border-radius:var(--radius-md)}
.rt-prose > :first-child img,.rt-prose .rt-capa img{width:100%;aspect-ratio:16/8;object-fit:cover;border-radius:var(--radius-lg)}
.rt-prose .separator{text-align:center}
.rt-prose a[imageanchor]{display:block;margin:0!important}
.rt-article-foot{max-width:68ch;margin:var(--space-7) auto 0;padding-top:var(--space-6);border-top:1px solid var(--line);display:flex;flex-wrap:wrap;gap:var(--space-3);align-items:center;justify-content:space-between}
.rt-labels{display:flex;flex-wrap:wrap;gap:var(--space-2)}
/* Texto das postagens: ignora cor, fundo e fonte colados pelo editor do Blogger */
.rt-prose{color:var(--ink-body)!important;background:transparent!important}
.rt-prose *:not(img):not(svg):not(path){background:transparent!important;background-color:transparent!important;color:inherit!important;font-family:inherit!important;font-size:inherit!important;line-height:inherit!important}
.rt .rt-prose h1,.rt .rt-prose h2,.rt .rt-prose h3,.rt .rt-prose h4{color:var(--ink)!important;font-family:var(--font-display)!important}
.rt .rt-prose h2{font-size:28px!important;line-height:34px!important}
.rt .rt-prose h3,.rt .rt-prose h4{font-size:22px!important;line-height:28px!important}
.rt .rt-prose strong,.rt .rt-prose b{color:var(--ink)!important}
.rt .rt-prose a{color:var(--link)!important}
.rt .rt-prose blockquote{background:var(--surface-sky)!important;color:var(--ink)!important;font-family:var(--font-display)!important;font-size:21px!important;line-height:30px!important}
@media (max-width:640px){.rt .rt-prose h2{font-size:24px!important;line-height:30px!important}}
.rt-egg{position:fixed;inset:0;z-index:1000;background:rgba(5,12,30,.88);display:flex;align-items:center;justify-content:center;padding:var(--space-4)}
.rt-egg[hidden]{display:none}
.rt-egg-box{width:min(1100px,100%,calc((100vh - 120px) * 1.6));background:#000;border-radius:var(--radius-md);overflow:hidden;box-shadow:0 20px 60px rgba(0,0,0,.6)}
.rt-egg-bar{display:flex;align-items:center;justify-content:space-between;gap:var(--space-3);padding:var(--space-2) var(--space-4);background:#0b1a3d;color:#eaf6fc;font:600 14px/20px var(--font-sans)}
.rt-egg-bar a{color:#5ed6da}
.rt-egg-close{background:none;border:1.5px solid rgba(234,246,252,.5);color:#eaf6fc;border-radius:var(--radius-pill);width:36px;height:36px;cursor:pointer;font-size:18px;line-height:1}
.rt-egg-stage{position:relative;width:100%;aspect-ratio:16/10;overflow:hidden;background:#000}
.rt-egg-stage iframe{position:absolute;top:0;left:0;width:640px;height:400px;border:0;background:#000;transform-origin:0 0}
.rt-data-post{display:none!important}
.rt-art-media{position:relative}
.rt-ph{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:6px;padding:var(--space-5);background:#0b2975;color:#caf5f7;text-align:center}
.rt-ph-pin{color:#1cabb0;font-size:22px;line-height:1}
.rt-ph-place{font:600 22px/28px var(--font-display);color:#ffffff}
.rt-ph-brand{font:700 11px/16px var(--font-sans);letter-spacing:.12em;text-transform:uppercase;color:#caf5f7}
.rt-article-cover{position:relative}
.rt-ph-lg .rt-ph-place{font-size:36px;line-height:42px}
#sobre{padding-bottom:0}
.rt-about{display:grid;grid-template-columns:1fr 1.1fr;background:var(--surface);border:1px solid var(--line);border-radius:var(--radius-lg);overflow:hidden;box-shadow:var(--shadow-md)}
.rt-about-media{position:relative;min-height:420px;background:var(--surface-sky)}
.rt-about-media img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}
.rt-about-body{padding:var(--space-7);display:flex;flex-direction:column;gap:var(--space-4);justify-content:center}
.rt-about-body h2{font-size:32px;line-height:38px;letter-spacing:-.01em}
.rt-about-list{list-style:none;margin:var(--space-2) 0 0;padding:0;display:flex;flex-direction:column;gap:var(--space-4)}
.rt-about-list li{display:flex;gap:var(--space-3);align-items:flex-start}
.rt-about-list strong{display:block;color:var(--ink);font-size:16px;line-height:22px}
.rt-about-list span{font-size:15px;line-height:22px}
.rt-about-icon{flex:none;width:40px;height:40px;border-radius:var(--radius-pill);background:var(--mist);color:var(--ink);display:inline-flex;align-items:center;justify-content:center}
.rt-about .rt-hero-actions{margin-top:var(--space-3)}
#rt-grid-feed:empty{display:none}
@media (max-width:1080px){ .rt-about{grid-template-columns:1fr} .rt-about-media{min-height:260px} }
@media (max-width:640px){ .rt-logo img{height:48px} .rt-about-body{padding:var(--space-5)} .rt-about-body h2{font-size:26px;line-height:32px} .rt-search-form{flex-direction:column} }
